            c1_structure: "**常用血液成分与适应证对照表**\n| 成分 | 主要作用 | 适应证 |\n|---|---|---|\n| 红细胞 | 携氧 | 急性失血、慢性贫血(Hb<70) |\n| 血小板 | 止血 | <10×10⁹/L 或有出血 |\n| FFP | 凝血因子+蛋白 | 凝血障碍、肝病、TTP |\n| 冷沉淀 | 纤维蛋白原、VIII、vWF | DIC、血友病甲 |\n| 白蛋白 | 扩容、结合毒素 | 低蛋白水肿、肝硬化 |",
