            c1_conclusion: "**必背结论**\n1. 红细胞指征：急性失血>30%血容量或 Hb<70g/L；70-100g/L 据心肺与出血速度定。\n2. 大量输血 1:1:1，补钙防枸橼酸中毒，保温防低体温，防稀释性凝血病。\n3. 溶血反应（ABO不合）：立即停血、维持血压尿量、碱化尿液、利尿、激素。\n4. 三查八对防差错；首选自身输血（术前贮存、稀释、回收）。\n5. TRALI、TA-GVHD 为严重并发症，免疫低下者用辐照血。\n> 一句话锁定: 输血看指征与成分；溶血反应停血+补液+碱化尿液；大量血1:1:1补钙。",
            c2_condition: "急性大出血、围术期贫血、凝血因子缺乏、血小板减少伴出血、低蛋白血症。",
            c2_application: "1. 成分输血选择（红细胞/血小板/血浆/冷沉淀）。\n2. 大量输血方案（MTP）启动与配比。\n3. 输血反应识别与紧急处理。\n4. 自体输血（贮存式、稀释式、回收式）实施。",
            c2_questiontype: "常见考法：输血指征、成分选择、溶血反应处理、并发症鉴别。\n例题：输血中突发寒战高热、腰背酸痛、血红蛋白尿、休克，如何处置？**答案**：高度怀疑急性溶血反应，立即停用血液、保持静脉通路与尿量（利尿）、碱化尿液（碳酸氢钠）、维持血压、抗休克与肾保护，必要时透析。",
            c2_variant: "1. 为什么大量输血要补钙？\n2. 库存血为何可致高钾血症？\n3. TRALI 与心源性肺水肿如何鉴别？\n4. 免疫抑制患者为何需辐照血？\n5. 自体输血的三种方式？",
            c2_boundary: "1. Hb>100g/L 一般不需红细胞；70-100g/L 个体化处理。\n2. 血浆不能当营养或单纯扩容滥用。\n3. 血小板输注效果受免疫破坏影响。",
            c3_error: "1. 把血浆当营养/扩容剂滥用。\n2. 溶血反应未立即停止输血并碱化尿液。\n3. 发热反应当过敏处理、未停血查明。\n4. 大量输血不补钙、不保温致枸橼酸/低体温并发症。\n5. 用库存血给新生儿/免疫低下者未辐照致 TA-GVHD。\n6. 非必要全血输注增加负担与风险。\n7. 三查八对流于形式致 ABO 不合。\n8. 血小板<10×10⁹/L 出血仍不及时输注。",
            c3_confuse: "| 对照 | A | B |\n|---|---|---|\n| 急性溶血 vs 发热反应 | ABO不合、血红蛋白尿、腰痛 | 非溶血、寒战高热无血尿 |\n| TRALI vs 循环超负荷 | 非心源性肺水肿、低氧 | 容量过多、颈静脉怒张 |\n| 过敏 vs 溶血 | 皮疹瘙痒荨麻疹 | 腰痛血红蛋白尿 |\n| 自身输血 vs 异体 | 无传染/排异 | 有风险需配血 |",
            c3_errortype: "指征错、成分错、反应识别错、处置延误、安全核查疏漏。",
            c4_related: "休克、DIC、肝衰竭、急性失血、凝血障碍。",
            c4_hook: "输血看指征与成分；溶血停血+补液+碱化；大量1:1:1补钙。\n> 反向自检钩子: 若处置溶血反应未提「立即停血」，第一步就错。",
            c4_forget: "大量输血公式 R:B:P≈1:1:1，且要补钙、保温。",
            c4_lastreview: "",
