            c1_keywords: "关键词：腹膜炎、转移性右下腹痛、麦氏点、反跳痛、肌紧张、板状腹、阑尾切除、膈下游离气体、腹腔脓肿。\n\n**触发式联想**\n| 看到 | 立刻想到 |\n|---|---|\n| 上腹痛→数小时后固定右下腹 | 转移性右下腹痛（阑尾炎） |\n| 麦氏点压痛+反跳痛 | 阑尾炎体征 |\n| 全腹压痛反跳痛肌紧张 | 弥漫性腹膜炎 |\n| 突发上腹剧痛、腹硬如板 | 胃十二指肠穿孔 |\n| 阑尾炎术后盆腔包块、发热 | 阑尾周围脓肿 |\n| 膈下游离气体 | 空腔脏器穿孔 |",
