            c1_conclusion: "**必背结论**\n1. 阑尾炎：病史（转移性右下腹痛）+ 体征（麦氏点压痛、反跳痛、肌紧张）+ 影像（超声/CT）诊断；治疗以阑尾切除术为主，穿孔者抗感染+手术。\n2. 腹膜炎「三联征」：腹痛 + 压痛反跳痛肌紧张（腹膜刺激征）+ 肠鸣音减弱/消失。\n3. 处理原则：半卧位（减少毒素吸收）、禁食胃肠减压、广谱抗生素、纠正水电紊乱，并尽快处理原发病（穿孔修补/阑尾切除/胆囊切除）。\n4. 阑尾周围脓肿：先抗感染/引流，3个月后再切阑尾。\n5. 小儿/老人/孕妇阑尾炎症状不典型，警惕穿孔。\n> 一句话锁定: 阑尾炎=转移右下腹痛+麦氏点；腹膜炎=压痛反跳痛肌紧张；穿孔要手术查病因。",
