            c2_questiontype: "常见考法：阑尾炎典型表现、腹膜炎三联征、手术指征、并发症、鉴别诊断。\n例题：急性阑尾炎最常见的早期表现是什么？**答案**：转移性右下腹痛——初为脐周或上腹隐痛（内脏神经），数小时后炎症波及壁层腹膜定位至右下腹麦氏点，是阑尾炎特征性病史。",
