            c3_error: "1. 把胃溃疡当十二指肠溃疡治，忽略癌变可能。\n2. 胃癌只做胃镜未做CT分期，遗漏远处转移。\n3. 胃大部切除后倾倒综合征未识别与饮食指导。\n4. 穿孔未查膈下游离气体仅凭腹痛。\n5. 幽门梗阻未纠正水电紊乱即手术。\n6. H.pylori阳性溃疡未根除致复发。\n7. 溃疡出血未内镜止血盲目手术。\n8. 把胃癌左锁骨上淋巴结当炎症。\n9. 术后残胃忽略随访（残胃癌）。",
