          title: "肝胆疾病与门静脉高压症",
          dims: {
            c1_concept: "**肝胆外科疾病**包括肝脓肿、肝肿瘤、门静脉高压症及胆石症、胆道感染。**加粗核心概念**：胆道梗阻感染致「Charcot三联征（腹痛、寒战高热、黄疸）」，最危重AOSC须「先引流」；门脉高压出血急救「先药物/内镜稳定再评估手术」。\n> 核心界定: 急性梗阻性化脓性胆管炎（AOSC）是外科急症，解除梗阻胆道引流优先于一切。",
            c1_keywords: "关键词：肝脓肿、肝癌、门静脉高压、食管胃底静脉曲张、胆石症、急性胆囊炎、Murphy征、Charcot三联征、Reynolds五联征、ERCP、T管、TIPS。\n\n**触发式联想**\n| 看到 | 立刻想到 |\n|---|---|\n| 右上腹痛+发热+黄疸 | Charcot三联征（胆管炎） |\n| 三联征+休克+神志变 | Reynolds五联（AOSC） |\n| 右上腹压痛、吸气屏气 | Murphy征（胆囊炎） |\n| 肝硬化+呕血黑便 | 食管胃底静脉破裂 |\n| 乙肝/肝硬化+AFP↑ | 肝癌可疑 |\n| 突发剧痛、板状腹 | 胆囊/胃肠穿孔 |",
            c1_principle: "## 一、胆道机制\n胆汁淤积/结石梗阻→细菌繁殖→胆囊炎/胆管炎；结石下移致胆绞痛，嵌顿致胆囊积液/穿孔。\n## 二、门脉高压机制\n肝硬化→肝内血流阻力↑→门静脉压↑→脾大脾亢、腹水、食管胃底静脉曲张；曲张静脉破裂→致命性呕血。\n## 三、肝癌机制\n乙肝/丙肝→肝硬化→异型增生→肝癌；AFP为重要标志物。",
            c1_structure: "**肝胆常见急症对照表**\n| 疾病 | 典型表现 | 关键体征/检查 |\n|---|---|---|\n| 急性胆囊炎 | 右上腹痛向右肩放 | Murphy征(+) |\n| 急性胆管炎 | 腹痛+高热+黄疸 | Charcot三联征 |\n| AOSC | 三联征+休克+神智 | Reynolds五联征 |\n| 胆总管结石 | 黄疸+胆管扩张 | ERCP/MRCP |\n| 肝癌 | 肝区痛、AFP↑ | 影像+活检 |\n| 门脉高压出血 | 呕血黑便、肝硬化 | 胃镜见曲张静脉 |",
            c1_variables: "| 变量 | 变化 | 后果 |\n|---|---|---|\n| 胆道梗阻 | 完全 | 胆管炎/AOSC |\n| 结石位置 | 胆总管 | 黄疸重 |\n| 肝功能 | Child分级差 | 手术风险↑ |\n| 门脉压力 | 高 | 出血风险 |\n| AFP | 显著↑ | 肝癌提示 |",
            c1_conclusion: "**必背结论**\n1. 胆囊结石：无症状可观察；有症状/并发症（息肉>1cm、胆囊壁厚）行胆囊切除（腔镜）。\n2. 胆管结石/胆管炎：抗生素+胆道引流（ENBD/PTCD），必要时ERCP取石或胆总管探查+T管引流。\n3. AOSC（雷诺五联）：立即减压引流是救命关键，抗休克同时尽快ERCP/手术。\n4. 肝癌：早期手术切除/消融/肝移植；中晚期TACE、靶向（索拉非尼）+免疫。\n5. 门脉高压出血：药物（生长抑素/血管加压素）+ 内镜套扎/硬化 + TIPS；稳定后手术断流（贲门周围血管离断）或分流。\n> 一句话锁定: 肝胆=胆石症/胆管炎/肝癌/门脉高压；AOSC先引流；门脉高压出血先内镜/TIPS。",
            c2_condition: "右上腹痛伴发热黄疸、肝区疼痛发热、肝硬化呕血黑便、腹部包块、Murphy征阳性。",
            c2_application: "1. 胆囊结石与胆管结石鉴别、手术指征。\n2. 急性胆管炎/AOSC紧急处理（引流优先）。\n3. 肝癌筛查（AFP+影像）与分期治疗。\n4. 门脉高压出血急救（药物/内镜/TIPS/手术）。",
            c2_questiontype: "常见考法：Charcot三联征、Murphy征、AOSC处理、肝癌诊断、门脉高压表现与急救。\n例题：急性梗阻性化脓性胆管炎（AOSC）最关键的治疗措施是什么？**答案**：紧急胆道减压引流（ERCP鼻胆管引流/PTCD或手术T管引流），解除梗阻是逆转休克与感染的核心，抗生素与抗休克仅为辅助，拖延引流可迅速致死。",
            c2_variant: "1. T管引流的目的与拔管指征？\n2. 门脉高压三大临床表现及机制？\n3. 肝癌与肝脓肿在影像上如何鉴别？\n4. 为何门脉高压出血先内镜/TIPS而非急手术？\n5. Child-Pugh分级对手术决策的意义？",
            c2_boundary: "1. 胆囊结石可无症状；胆管结石常伴黄疸与胆管扩张。\n2. 急性胆囊炎（Murphy征、无/轻黄疸）≠ 急性胆管炎（Charcot三联、黄疸重）。\n3. 门脉高压出血须先稳定再择期手术，避免急诊高死亡率。",
            c3_error: "1. AOSC未先引流只给抗生素，致休克死亡。\n2. 肝癌AFP正常即排除肝癌（部分AFP阴性）。\n3. 门脉高压出血未先药物/内镜稳定就急诊手术（死亡率高）。\n4. 胆囊穿孔未及时处理致胆汁性腹膜炎。\n5. 胆总管探查后未放T管或过早拔T管致胆瘘。\n6. 肝脓肿未穿刺/切开引流单用抗生素。\n7. 把黄疸都当肝炎忽略梗阻性（结石/肿瘤）。\n8. 肝硬化脾亢患者手术出血风险未评估。\n9. ERCP后胰腺炎并发症未监测。",
            c3_confuse: "| 对照 | A | B |\n|---|---|---|\n| 胆囊炎 vs 胆管炎 | Murphy征、轻黄疸 | Charcot三联、重黄疸 |\n| AOSC vs 单纯胆管炎 | 加休克/神志（五联） | 仅三联 |\n| 胆囊结石 vs 胆管结石 | 多无黄疸 | 黄疸+胆管扩张 |\n| 肝癌 vs 肝脓肿 | AFP↑、占位实性 | 发热、液性腔 |",
            c3_errortype: "引流优先级错、诊断遗漏、出血急救顺序错、拔管时机错。",
            c4_related: "乙肝、肝硬化、胆囊结石、急性胰腺炎、上消化道出血、肝性脑病。",
            c4_hook: "肝胆=胆石症/胆管炎/肝癌/门脉高压；AOSC先引流；门脉高压出血先内镜/TIPS。\n> 反向自检钩子: 若AOSC处理未把「胆道引流」置首位，必错。",
            c4_forget: "AOSC=Charcot三联+休克/神志（Reynolds五联），先引流救命。",
            c4_lastreview: "",
            c4_nextreview: "",
            c5_mastery: "中",
            c5_weak: "是",
            c5_weaksource: "胆管炎处理与肝胆鉴别",
            c5_errfreq: "高",
            c5_impact: "高",
            c5_priority: "高",
          }
