            c1_concept: "**提示：骨折专有体征（畸形、异常活动、骨擦感）三者具其一即可诊断骨折；一般损伤只有疼痛肿胀，属非专有体征。** 骨折是骨的完整性和/或连续性中断，可由创伤、骨骼疾病或积累性劳损引起。",
            c1_keywords: "骨折、专有体征、移位、畸形、骨擦感、异常活动、复位、固定、功能锻炼、骨筋膜室综合征、脂肪栓塞、骨不连",
            c1_principle: "外力超过骨强度→骨皮质/骨小梁断裂；局部出血炎症→血肿机化→纤维骨痂→骨性骨痂→改建塑形（临床愈合约4-8周，骨性愈合数月）。**要点：骨折愈合依赖良好血供与稳定固定，过度活动或分离会致骨不连/延迟愈合。**",
            c1_structure: "分类与对照表：\n| 分类维度 | 类型 | 说明 |\n| 皮肤完整 | 闭合性/开放性 | 开放骨折需急诊清创，按Gustilo分型 |\n| 断裂程度 | 完全/不完全 | 青枝骨折多见于儿童 |\n| 稳定性 | 稳定/不稳定 | 稳定者可手法复位石膏固定 |\n| 移位方向 | 成角/侧方/短缩/分离/旋转 | 复位须纠正全部移位 |\n骨折专有体征表：\n| 专有体征 | 表现 | 临床意义 |\n| 畸形 | 缩短/成角/旋转 | 三者之一即可诊断 |\n| 异常活动 | 非关节部位出现活动 | 提示完全骨折 |\n| 骨擦音/骨擦感 | 断端摩擦 | 一般不主动检查以免加重损伤",
            c1_variables: "| 变量 | 对愈合/预后的影响 |\n| 暴力大小方向 | 决定移位与粉碎程度 |\n| 骨骼质量 | 骨质疏松更易折、愈合慢 |\n| 年龄 | 儿童塑形强、老人愈合慢 |\n| 血供 | 决定愈合速度与坏死风险 |\n| 软组织损伤 | 开放/毁损影响固定与感染风险",
            c1_conclusion: "**治疗原则=复位+固定+功能锻炼。** 复位：手法或切开；固定：石膏/夹板/牵引/外固定架/内固定；功能锻炼防肌萎缩与关节僵硬。并发症：早期（休克、脂肪栓塞、重要血管神经损伤、骨筋膜室综合征——5P征：疼痛/苍白/无脉/感觉异常/麻痹，须急诊切开减压）；晚期（坠积性肺炎、压疮、DVT、骨不连、畸形愈合、创伤性关节炎）。",
            c2_condition: "外伤后局部疼痛、肿胀、畸形、活动障碍、骨擦感；开放骨折见伤口与骨端外露。",
            c2_application: "X线（正侧位、包括上下关节）首选；CT/MRI看关节内与软组织；复位固定方案选择；骨筋膜室综合征早期识别与急诊处理；康复计划制定。",
            c2_questiontype: "①骨折专有体征；②治疗三大原则；③早期/晚期并发症；④骨筋膜室综合征5P表现；⑤开放骨折急救处理。",
            c2_variant: "【例题】骨折的专有体征有哪些？\n答：畸形、异常活动、骨擦音/骨擦感，三者具其一即可诊断骨折；一般损伤（疼痛、肿胀、瘀斑）为非专有体征，不能据此确诊。",
            c2_boundary: "骨折 vs 脱位（脱位为关节面失去对合、弹性固定、关节盂空虚）vs 软组织损伤；开放骨折（Gustilo分型）须6-8h内彻底清创；病理骨折（骨病基础上轻微外力）治疗须兼治原发病。",
            c3_error: "①忽略骨筋膜室综合征早期5P征，延误切开致Volkmann挛缩；②开放骨折清创不彻底致慢性骨髓炎；③关节内骨折未达解剖复位遗留创伤性关节炎；④过度牵引致骨折分离不愈合；⑤只重固定忽视功能锻炼致关节僵硬；⑥儿童青枝骨折误判为软组织伤；⑦脂肪栓塞只想到肺，忽略脑脂肪栓塞（烦躁、意识障碍）；⑧骨不连盲目再固定未改善血供；⑨把异常活动反复主动检查加重损伤。",
            c3_confuse: "| 易混概念 | 关键区别 |\n| 畸形(骨折专有) vs 弹性固定(脱位) | 骨折为成角缩短，脱位有弹性回弹固定感 |\n| 骨擦感 vs 关节弹响 | 骨折为断端摩擦，弹响为韧带/软骨 |\n| 脂肪栓塞 vs 空气栓塞 | 脂肪来自骨髓/脂肪组织，空气来自静脉损伤 |\n| 骨不连 vs 延迟愈合 | 骨不连X线见断端硬化、无骨痂；延迟愈合仍有骨痂生长",
            c3_errortype: "并发症漏诊型（骨筋膜室/脂肪栓塞）、复位固定错（过度牵引/未解剖复位）、康复缺失型。",
            c4_related: "创伤、休克、脂肪栓塞综合征、深静脉血栓、压疮、骨质疏松。",
            c4_hook: "触发联想：①见「外伤后畸形+骨擦感」→骨折专有体征，立刻想固定与X线；②见「剧痛+被动牵拉痛+5P」→骨筋膜室综合征，急诊切开；③见「长骨干骨折+呼吸困难/烦躁」→脂肪栓塞；④见「老年髋部摔伤」→股骨颈/转子间骨折；⑤见「儿童上肢牵拉痛」→青枝/肱骨髁上骨折。",
            c4_forget: "易忘：骨筋膜室5P具体内容、脂肪栓塞可累及脑、「复位→固定→功能锻炼」三原则顺序。",
