            c1_principle: "骨组织细胞异常增殖；良性生长慢、边界清；恶性浸润破坏、边界不清、易转移；转移瘤来自他处癌（血行播散）。",
            c1_structure: "常见骨肿瘤对照表：\n| 肿瘤 | 年龄/部位 | 典型X线 | 性质 |\n| 骨软骨瘤 | 青年、骨干骺端 | 带蒂骨性突起、软骨帽 | 良性（最常见） |\n| 骨巨细胞瘤 | 20-40岁、骨端 | 肥皂泡样、偏心 |\n| 骨肉瘤 | 青少年、长骨干骺端 | Codman三角/日光放射 | 恶性 |\n| 尤文肉瘤 | 儿童、骨干 | 洋葱皮样骨膜反应 | 恶性 |\n| 转移瘤 | 中老年、脊柱/骨盆 | 溶骨/成骨破坏 | 恶性（最常见） |",
            c1_variables: "| 变量 | 影响 |\n| 年龄 | 青少年肉瘤、中老年转移 |\n| 部位 | 干骺端多恶性、骨端多巨细胞瘤 |\n| 生长速度/疼痛 | 恶性夜间痛、进展快 |\n| 病理性骨折 | 提示骨质破坏严重 |",
