            c2_boundary: "骨囊肿、纤维结构不良等良性病变须鉴别；病理性骨折提示骨质破坏严重；转移性骨肿瘤（最常见）须与原发性鉴别并寻找原发灶。",
            c3_error: "①未活检就按良性刮除恶性肿瘤（致扩散）；②骨肉瘤未做新辅助化疗直接截肢（应保肢+化疗）；③转移瘤未找原发灶；④把骨软骨瘤（良性）误判为恶性；⑤尤文肉瘤只手术忽略放化疗敏感。",
            c3_confuse: "| 易混概念 | 区别 |\n| 骨软骨瘤(良性) vs 骨肉瘤(恶性) | 前者带蒂骨突、无症状，后者破坏+骨膜反应+肿块 |\n| 骨巨细胞瘤 vs 骨囊肿 | 巨细胞瘤肥皂泡、偏心，囊肿透亮、中心性 |\n| 转移瘤 vs 原发肉瘤 | 转移有原发癌史、多发，原发单发青少年 |",
