            c1_structure: "表现与分级对照表：\n| 分期 | 表现 |\n| 早期 | 间歇性跛行（行走痛、休息缓解） |\n| 进展 | 静息痛（夜间加重） |\n| 晚期 | 肢端溃疡、坏疽 |\nRutherford分级按缺血程度分0-6级，指导治疗决策。好发于下肢股腘/髂动脉。",
            c1_variables: "| 变量 | 影响 |\n| 吸烟/糖尿病/高脂血症 | 加速斑块进展 |\n| 病变部位 | 髂/股腘决定术式 |\n| 合并冠心病/卒中 | 全身动脉硬化标志 |",
            c1_conclusion: "**诊断：ABI降低(<0.9)、超声、CTA/MRA、DSA(金标准)。** 治疗：戒烟+控制危险因素+步行锻炼+抗血小板(阿司匹林/氯吡格雷)+他汀；间歇性跛行用西洛他唑；严重缺血行腔内治疗(球囊/支架)或旁路移植。口诀：戒烟控危他汀抗板，重症介入或搭桥。",
            c2_condition: "中老年、吸烟/糖尿病、间歇性跛行、静息痛、肢端溃疡。",
