            c2_questiontype: "①间歇性跛行机制；②Rutherford分级；③治疗原则；④手术/腔内指征。",
            c2_variant: "【例题】下肢动脉硬化闭塞症首选影像学检查是什么？\n答：无创首选下肢动脉超声与CTA；确诊/术前评估金标准为DSA（数字减影血管造影）；ABI为简便筛查。",
            c2_boundary: "需与Buerger病（青年男性、游走性血栓性静脉炎）、腰椎管狭窄（神经性跛行，下垂缓解）鉴别；间歇性跛行与神经源性跛行方向相反（前者行走诱发、休息缓解）。",
            c3_error: "①静息痛/溃疡仍只保守治疗错过血运重建；②未戒烟控危只给扩血管药；③把间歇性跛行当椎管狭窄；④腔内治疗后未双抗血小板+他汀维持。",
            c3_confuse: "| 易混概念 | 区别 |\n| ASO vs Buerger病 | ASO老年多危大中动脉；Buerger青年男吸烟中小血管+游走静脉炎 |\n| 血管性跛行 vs 神经性跛行 | 血管行走痛休息缓解；神经下垂/弯腰缓解 |\n| 间歇性跛行 vs 静息痛 | 前者运动诱发，后者静息持续、提示重症 |",
            c3_errortype: "治疗延误（未血运重建）、鉴别诊断错。",
