            c2_variant: "【例题】Buerger病患者最重要的治疗措施是什么？\n答：严格、彻底戒烟——这是唯一能阻止病变进展的有效措施；其他扩血管、抗血小板及手术均不能替代戒烟。",
            c2_boundary: "需与雷诺综合征（发作性苍白-紫绀-潮红、无器质性闭塞）、肢端发绀、冻伤、ASO鉴别；Buerger病无粥样硬化高危因素。",
            c3_error: "①未强调戒烟只给扩血管药（无效）；②把Buerger当ASO做动脉内膜剥脱；③忽视游走性静脉炎线索漏诊；④过早截肢未先保守治疗。",
